// Общее для тестов «תשתית SSR/SSG לדפים ציבוריים» (#be4863). Прод, только GET.
import { expect, APIRequestContext, BrowserContext } from '@playwright/test';

export const LOAD = { timeout: 25_000 };
const SAFE_METHODS = ['GET', 'HEAD', 'OPTIONS'];

export const PRIVATE_PATHS = [
  '/messages',
  '/addbusiness',
  '/mybusinesses',
  '/userprofile',
  '/changepassword',
  '/favoritesandconversations',
  '/savedsearches',
];

export const SERVICE_PATHS = ['/admin', '/auth'];

const STATIC_PUBLIC = ['/', '/search', '/packages', '/calculator', '/buyerlistings'];

export function decodeEntities(s: string): string {
  return s
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(parseInt(d, 10)))
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&');
}

export const stripTags = (s: string) => decodeEntities(s.replace(/<[^>]*>/g, ' ')).replace(/\s+/g, ' ').trim();

/** content всех <meta name="robots">. */
export function robotsMeta(html: string): string[] {
  const out: string[] = [];
  for (const tag of html.match(/<meta\b[^>]*>/gi) ?? []) {
    if (!/\bname\s*=\s*["']robots["']/i.test(tag)) continue;
    const m = tag.match(/\bcontent\s*=\s*"([^"]*)"|\bcontent\s*=\s*'([^']*)'/i);
    if (m) out.push(decodeEntities(m[1] ?? m[2]).trim());
  }
  return out;
}

/** Содержимое #root от открывающего тега до конца документа (SSR-блок лежит внутри). */
export function rootTail(html: string): string | null {
  const i = html.search(/<div\s+id=["']root["'][^>]*>/i);
  return i < 0 ? null : html.slice(i);
}

/** Публичные адреса: статические + категория из sitemap + карточка из сырого /search (без выдуманных значений). */
export async function publicPaths(request: APIRequestContext): Promise<string[]> {
  const sitemap = await (await request.get('/sitemap.xml')).text();
  const cat = sitemap.match(/<loc>[^<]*?(\/search\?category=[^<]+)<\/loc>/)?.[1];
  expect(cat, 'в sitemap.xml есть /search?category=').toBeTruthy();
  const search = await (await request.get('/search')).text();
  const id = search.match(/href="\/businessdetail\?id=([0-9a-f-]+)/)?.[1];
  expect(id, 'в сыром /search есть ссылка /businessdetail?id=').toBeTruthy();
  return [...STATIC_PUBLIC.slice(0, 2), decodeEntities(cat!), `/businessdetail?id=${id}`, ...STATIC_PUBLIC.slice(2)];
}

/** Вызывать до первого перехода: не-GET обрываются, cookie — «только необходимые». */
export async function prepareReadOnly(context: BrowserContext) {
  await context.route('**/*', (route) =>
    SAFE_METHODS.includes(route.request().method()) ? route.fallback() : route.abort('blockedbyclient'),
  );
  await context.addInitScript(() => {
    try {
      if (!localStorage.getItem('cookie-consent-v2')) {
        localStorage.setItem(
          'cookie-consent-v2',
          JSON.stringify({ essential: true, performance: false, marketing: false, updatedAt: new Date().toISOString() }),
        );
      }
    } catch {}
  });
}
